content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体的法律合规性与信息真实性",
            "check_points": [
                "通过权威工商数据库（如国家企业信用信息公示系统）核查该主体是否存在未结涉法涉诉案件、失信记录、严重违法失信名单等重大风险信息",
                "核对营业执照所载经营范围，确认合同标的（如服务内容、产品类型）属于其登记的经营范围内",
                "逐项比对合同首部列明的主体信息（联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "若合同涉及软件采购或技术产品，核查卖方是否拥有该软件/产品的核心知识产权（如著作权登记证书、专利证书、授权链文件），并确认知识产权归属及许可范围明确"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保合同核心条款结构完整、要素齐备、逻辑严密",
            "check_points": [
                "检查合同是否完整包含以下必备条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用约定、产品质量保证/服务标准、交付方式与地点、验收标准与流程、完成时限（含里程碑节点）、违约责任、司法管辖法院/仲裁机构、不可抗力定义与处理机制、廉洁承诺条款、合同变更程序、合同份数及效力说明、电子送达效力约定",
                "确认合同中已明确指定主要项目负责人，并完整载明其姓名、身份证号码、联系电话；如为团队履约，应注明负责人权责边界",
                "采购内容须具体化：品种、规格、型号、等级、花色等须清晰列明；复杂标的应通过附件（如技术规格书、配置清单）予以固化，附件须与正文具有同等法律效力并明确引用关系",
                "合同金额条款须同时载明：数量单位、单价（含税/不含税）、总价、币种（如人民币/USD）、大小写金额一致；计量单位须规范（如‘套’‘台’‘人·日’），避免歧义",
                "付款计划须分阶段明确：各节点触发条件（如‘签署后5个工作日内’‘初验合格后10日内’）、支付比例、对应金额、发票类型（增值税专用发票/普通发票）、开票时间要求；预留不低于5%—10%尾款于免费维保期届满且无质量争议后支付"
            ]
        },
        {
            "id": "C3",
            "section": "合同期限与时间表述审查",
            "criterion": "确保期限约定精准、可执行，杜绝模糊表述",
            "check_points": [
                "合同期限须以起止日期（年/月/日）或明确计算方式（如‘自2025年1月1日起至2026年12月31日止’）载明，禁止使用‘长期’‘永久’等不确定表述",
                "所有时间节点须明确定义计时基准：注明‘自然日’或‘工作日’；季度/年度起算须明确（如‘自合同生效日起满12个月’而非‘一年内’），避免‘第三个月末’等易生歧义表述",
                "关键期限（如交付期、验收期、维保期）须与付款节点、违约责任挂钩，形成闭环逻辑"
            ]
        },
        {
            "id": "C4",
            "section": "文本规范性与一致性审查",
            "criterion": "保障合同文本形式合法、语言严谨、内外统一",
            "check_points": [
                "全文通读校对：排查错别字、标点误用、语法错误、语义矛盾、标题层级混乱（如‘二、’下直接接‘（三）’）、编号断续等问题",
                "核验合同正文与所有附件（技术协议、服务清单、保密承诺等）中相同条款（如验收标准、违约金比例、知识产权归属）表述是否完全一致；不一致处须以正文为准或签署补充说明",
                "清除招标/谈判/比选等前置采购流程中的过程性用语（如‘本项目系经XX招标代理机构组织公开招标’‘响应人承诺’），统一替换为合同双方平等缔约语境下的规范表述",
                "合同首部‘甲方/乙方’名称、签约页‘签署单位全称’、落款印章名称三者须严格一致；不得出现简称、曾用名、注册名与实际签章名不符情形",
                "援引法律法规须为现行有效版本（如《民法典》合同编，非已废止的《合同法》），条文序号准确，不得虚构法条或援引地方性文件替代上位法",
                "合同正文末尾须独立成行、加粗标注‘以下为合同签署栏’或‘以下无正文’字样，防止被擅自增补条款"
            ]
        }
    ]
}
